method SquareRoot(N: nat) returns (result: nat)
  ensures result * result <= N
  ensures N < (result + 1) * (result + 1)
{
  // Handle special case for N = 0
  if N == 0 {
    return 0;
  }

  // Initialize variables for binary search
  var low := 0;
  var high := N;
  var mid := 0;

  // Perform binary search to find the integer square root
  while low < high {
    mid := (low + high) / 2;

    if mid * mid <= N {
      low := mid + 1; // Move to higher half
    } else {
      high := mid; // Move to lower half
    }
  }

  // Since low will be one more than the result after exiting the loop,
  // we should return low - 1 (the last valid mid).
  return low - 1;
}

