  ensures N < (result + 1) * (result + 1)
{
  if N == 0 {
    return 0; // The square root of 0 is 0
  }

  // Start with a range for binary search
  var low := 0;
  var high := N;

  var mid: nat;

  while low < high {
    mid := (low + high) / 2; // Calculate the midpoint
    if mid * mid <= N {
      low := mid + 1; // Move up the lower bound
    } else {
      high := mid; // Move down the upper bound
    }
  }

  // After the loop, low is the first number where low * low > N, so we return low - 1
  return low - 1;
}

