method DivisionFunction(x: nat, y: nat) returns (result: (int, int))
  ensures y == 0 ==> result.0 == x && result.1 == 0
  ensures y != 0 ==> result.1 * y + result.0 == x && 0 <= result.0 < y && 0 <= result.1
{
  if y == 0 {
    // If the divisor is zero, return the dividend as the remainder and 0 as the quotient
    result := (x, 0);
  } else {
    var r := x; // Start with the remainder equal to the dividend
    var q := 0; // Initialize the quotient to 0

    // Reduce r while it is greater than or equal to y
    while r >= y
      invariant r >= 0 && r < y || (q * y + r == x && 0 <= q)
    {
      r := r - y; // Subtract y from r
      q := q + 1; // Increment the quotient for each subtraction
    }

    result := (r, q); // Return the final remainder and quotient
  }
}

