method rotate(a: seq<int>, offset: int) returns (result: seq<int>)
  requires offset >= 0
  ensures |result| == |a|
  ensures forall i :: 0 <= i < |a| ==> result[i] == a[(i + offset) % |a|]
{
  if |a| == 0 {
    result := []; // Return an empty result for an empty input list
  } else {
    var n := |a|;
    // Adjust the offset to be within the bounds of the length of a
    var adjustedOffset := offset % n;
    result := new int[n]; // Create a new sequence of the same length as a

    // Populate the result with the rotated values
    var i := 0;
    while i < n
      invariant 0 <= i <= n
      invariant forall j :: 0 <= j < i ==> result[j] == a[(j + adjustedOffset) % n]
    {
      result[i] := a[(i + adjustedOffset) % n]; // Calculate the rotated position
      i := i + 1; // Move to the next index
    }
  }
}

