  } else {
    // Calculate the effective offset to handle cases where offset >= |a|.
    var n := |a|;
    var effectiveOffset := offset % n;

    // Initialize the result with the same length as a.
    result := new seq<int>(n);

    // Populate the result sequence with the rotated values.
    var i: int := 0;
    while i < n
      invariant 0 <= i <= n
      invariant |result| == n
    {
      result[i] := a[(i + effectiveOffset) % n];
      i := i + 1;
    }
  }
}

