method SelectionSort(a: seq<int>) returns (result: seq<int>)
  ensures forall i, j :: 0 <= i < j < |result| ==> result[i] <= result[j]
  ensures multiset(result) == multiset(a)
{
  var n := |a|;
  // Create a mutable array to hold the sorted elements
  var arr := new int[n];
  // Copy the input sequence to the mutable array
  var i := 0;
  while i < n
    invariant 0 <= i <= n
  {
    arr[i] := a[i];
    i := i + 1;
  }

  // Perform selection sort
  var sortedIndex := 0;
  while sortedIndex < n
    invariant 0 <= sortedIndex <= n
    invariant forall k :: 0 <= k < sortedIndex ==> arr[k] <= arr[sortedIndex] // sorted up to index sortedIndex
  {
    // Find the smallest element from the unsorted part
    var minIndex := sortedIndex;
    var j := sortedIndex + 1;
    while j < n
      invariant sortedIndex <= j <= n
      invariant minIndex <| n
    {
      if arr[j] < arr[minIndex] {
        minIndex := j;
      }
      j := j + 1;
    }

    // Swap the found smallest element with the first unsorted element
    if minIndex != sortedIndex {
      var temp := arr[sortedIndex];
      arr[sortedIndex] := arr[minIndex];
      arr[minIndex] := temp;
    }

    sortedIndex := sortedIndex + 1;
  }

  // Return the sorted array as a sequence
  result := arr;
}

