method SelectionSort(a: seq<int>) returns (result: seq<int>)
  ensures forall i, j :: 0 <= i < j < |result| ==> result[i] <= result[j]
  ensures multiset(result) == multiset(a)
{
  var n := |a|; // Length of the input sequence
  var sorted := new int[n]; // Array to hold sorted elements
  var copy := a; // Create a mutable copy of the input sequence

  var index := 0; // Index for filling the sorted array
  while index < n
    invariant 0 <= index <= n
    invariant multiset(sorted) == multiset(a) - multiset(copy) // Elements in sorted match elements removed from copy
  {
    var minIndex := index;
    // Find the minimum element in the unsorted portion
    var i := index;
    while i < n
      invariant index <= i <= n
      invariant minIndex >= index ==> copy[minIndex] <= copy[i]
    {
      if copy[i] < copy[minIndex] {
        minIndex := i;
      }
      i := i + 1;
    }

    // Swap the found minimum element with the first element of the unsorted portion
    sorted[index] := copy[minIndex];
    // Remove that element from the copy
    copy[minIndex] := copy[index]; // Move last element into the position of the min element
    index := index + 1; // Move to the next position in sorted
  }

  result := sorted; // Assign sorted array as the result
}

